-- Synthetic fixtures only; no provider calls. Every record/queued alert is rolled back.
begin;
create temporary table inbox_ctx(key text primary key,id uuid not null default gen_random_uuid());
insert into inbox_ctx(key) values('manager'),('member'),('other'),('parent'),('unverified'),('coach'),('org'),('org2'),('player'),('link'),('request_id');
grant select,insert,update on inbox_ctx to authenticated,anon;
insert into auth.users(id,email,email_confirmed_at,is_anonymous) select id,'inbox-test-'||id||'@example.invalid',case when key='unverified' then null else now() end,false from inbox_ctx where key in ('manager','member','other','parent','unverified','coach');
insert into public.staff_members(user_id,role,active) select id,case when key='coach' then 'coach' else 'manager' end,true from inbox_ctx where key in ('manager','coach');
insert into public.guardian_profiles(user_id,display_name) select id,'Synthetic guardian' from inbox_ctx where key='parent';
insert into public.coaching_players(id,first_name,last_name,programme,consent_confirmed,consent_recorded_by,created_by) select id,'Synthetic','Inbox','Assessment',true,(select id from inbox_ctx where key='manager'),(select id from inbox_ctx where key='manager') from inbox_ctx where key='player';
insert into public.guardian_player_links(guardian_id,player_id,approved_by) values((select id from inbox_ctx where key='parent'),(select id from inbox_ctx where key='player'),(select id from inbox_ctx where key='manager'));
insert into public.star_organisations(id,name,kind,created_by) select id,'Synthetic '||key,'school',(select id from inbox_ctx where key='manager') from inbox_ctx where key in ('org','org2');
insert into public.star_organisation_members(organisation_id,email,display_name,user_id,accepted_at,invited_by) select (select id from inbox_ctx where key=case when t.key='other' then 'org2' else 'org' end),'inbox-test-'||t.id||'@example.invalid','Test staff',t.id,now(),(select id from inbox_ctx where key='manager') from inbox_ctx t where key in ('member','other','unverified');
insert into public.star_organisation_players(id,organisation_id,player_id,created_by,approved_by,approved_at) values((select id from inbox_ctx where key='link'),(select id from inbox_ctx where key='org'),(select id from inbox_ctx where key='player'),(select id from inbox_ctx where key='manager'),(select id from inbox_ctx where key='parent'),now());
create function pg_temp.ok(value boolean,label text) returns void language plpgsql as $$begin if value is distinct from true then raise exception 'Inbox check failed: %',label; end if; end$$;
create function pg_temp.denied(action text,data jsonb default '{}') returns void language plpgsql as $$begin begin perform public.star_organisation_inbox(action,data); exception when others then return; end; raise exception 'Unexpected inbox access: %',action; end$$;
set local role anon;
select pg_temp.denied('list');
do $$begin begin perform public.star_organisation_email_worker(repeat('0',64),'claim'); exception when others then return; end; raise exception 'Wrong worker credential accepted'; end$$;
set local role authenticated;
select set_config('request.jwt.claim.sub',(select id::text from inbox_ctx where key='member'),true);
select pg_temp.denied('list'); -- organisation context is mandatory for external staff
select pg_temp.denied('list',jsonb_build_object('organisation_id',(select id from inbox_ctx where key='org2')));
insert into inbox_ctx(key,id) select 'general',(public.star_organisation_inbox('create',jsonb_build_object('organisation_id',(select id from inbox_ctx where key='org'),'subject','General check','body','Synthetic organisation message','client_id','11111111-1111-4111-8111-111111111111'))->>'thread_id')::uuid;
select pg_temp.ok((public.star_organisation_inbox('create',jsonb_build_object('organisation_id',(select id from inbox_ctx where key='org'),'subject','General check','body','Synthetic organisation message','client_id','11111111-1111-4111-8111-111111111111'))->>'thread_id')::uuid=(select id from inbox_ctx where key='general'),'new-thread retry is idempotent');
insert into inbox_ctx(key,id) select 'player_thread',(public.star_organisation_inbox('create',jsonb_build_object('organisation_id',(select id from inbox_ctx where key='org'),'link_id',(select id from inbox_ctx where key='link'),'subject','Player check','body','Synthetic selected player message','client_id',gen_random_uuid()))->>'thread_id')::uuid;
do $$begin begin perform * from star_private.org_messages; exception when insufficient_privilege then return; end; raise exception 'Raw messages readable'; end$$;
select set_config('request.jwt.claim.sub',(select id::text from inbox_ctx where key='other'),true);
select pg_temp.denied('thread',jsonb_build_object('organisation_id',(select id from inbox_ctx where key='org2'),'thread_id',(select id from inbox_ctx where key='general')));
select set_config('request.jwt.claim.sub',(select id::text from inbox_ctx where key='unverified'),true);
select pg_temp.denied('list',jsonb_build_object('organisation_id',(select id from inbox_ctx where key='org')));
select set_config('request.jwt.claim.sub',(select id::text from inbox_ctx where key='coach'),true);
select pg_temp.denied('list');
select set_config('request.jwt.claim.sub',(select id::text from inbox_ctx where key='manager'),true);
select pg_temp.ok((public.star_organisation_inbox('summary')->>'unread')::integer=2,'manager receives both incoming messages');
select pg_temp.ok(jsonb_array_length(public.star_organisation_inbox('thread',jsonb_build_object('thread_id',(select id from inbox_ctx where key='general')))->'messages')=1,'idempotent creation stored one message');
select public.star_organisation_inbox('read',jsonb_build_object('thread_id',(select id from inbox_ctx where key='general'),'through',(public.star_organisation_inbox('thread',jsonb_build_object('thread_id',(select id from inbox_ctx where key='general')))->'messages'->0->>'id')));
select pg_temp.ok((public.star_organisation_inbox('summary')->>'unread')::integer=1,'read only selected conversation');
select public.star_organisation_inbox('send',jsonb_build_object('thread_id',(select id from inbox_ctx where key='general'),'body','Synthetic STAR reply','client_id','22222222-2222-4222-8222-222222222222'));
select public.star_organisation_inbox('send',jsonb_build_object('thread_id',(select id from inbox_ctx where key='general'),'body','Synthetic STAR reply','client_id','22222222-2222-4222-8222-222222222222'));
select pg_temp.ok(jsonb_array_length(public.star_organisation_inbox('thread',jsonb_build_object('thread_id',(select id from inbox_ctx where key='general')))->'messages')=2,'reply retry is idempotent');
select public.star_organisation_portal('publish_update',jsonb_build_object('link_id',(select id from inbox_ctx where key='link'),'feedback','Synthetic shared feedback only','suggested_support','Practise scanning'));
select set_config('request.jwt.claim.sub',(select id::text from inbox_ctx where key='member'),true);
select pg_temp.ok((public.star_organisation_inbox('summary',jsonb_build_object('organisation_id',(select id from inbox_ctx where key='org')))->>'unread')::integer=2,'member receives reply and selected feedback');
select public.star_organisation_portal('request',jsonb_build_object('organisation_id',(select id from inbox_ctx where key='org'),'service','school_taster','details','Synthetic coaching request','venue','Test venue','preferred_dates','Friday'));
select public.star_organisation_portal('observation',jsonb_build_object('organisation_id',(select id from inbox_ctx where key='org'),'link_id',(select id from inbox_ctx where key='link'),'observation','Synthetic football observation'));
reset role;
select pg_temp.ok((select count(*)=1 from star_private.org_messages where sender_id=(select id from inbox_ctx where key='member') and kind='session_request'),'new session request appears in inbox');
select pg_temp.ok((select count(*)=1 from star_private.org_messages where sender_id=(select id from inbox_ctx where key='member') and kind='observation'),'observation appears in inbox');
select pg_temp.ok(not exists(select 1 from star_private.org_deliveries where recipient_id in (select id from inbox_ctx where key in ('other','unverified','coach'))),'no wrong-organisation, unverified or coach recipients');
-- Claim tokens, backoff, stale-finisher denial and exhausted-lease recovery.
create temporary table inbox_claims(payload jsonb);
insert into inbox_claims select public.star_organisation_email_worker((select decrypted_secret from vault.decrypted_secrets where name='organisation_email_worker_secret'),'claim');
select pg_temp.ok((select jsonb_array_length(payload)>0 from inbox_claims),'worker can claim due alerts');
select pg_temp.ok((select count(*)=jsonb_array_length((select payload from inbox_claims)) from star_private.org_deliveries where status='sending' and lease_until>now()),'claimed jobs have active token leases');
select public.star_organisation_email_worker((select decrypted_secret from vault.decrypted_secrets where name='organisation_email_worker_secret'),'finish',jsonb_build_object('id',payload->0->>'id','claim_token',payload->0->>'claim_token','status','retry')) from inbox_claims;
select pg_temp.ok((select d.status='pending' and d.available_at>now() and d.claim_token is null and d.attempts=1 from star_private.org_deliveries d where d.id=((select payload from inbox_claims)->0->>'id')::uuid),'transient delivery backs off without a live lease');
select pg_temp.ok((select public.star_organisation_email_worker((select decrypted_secret from vault.decrypted_secrets where name='organisation_email_worker_secret'),'finish',jsonb_build_object('id',payload->0->>'id','claim_token',payload->0->>'claim_token','status','sent')) is null from inbox_claims),'stale finisher cannot mark retried delivery sent');
update star_private.org_deliveries set status='sending',attempts=8,lease_until=now()-interval '1 second' where id=((select payload from inbox_claims)->0->>'id')::uuid;
select public.star_organisation_email_worker((select decrypted_secret from vault.decrypted_secrets where name='organisation_email_worker_secret'),'claim');
select pg_temp.ok((select status='failed' and claim_token is null from star_private.org_deliveries where id=((select payload from inbox_claims)->0->>'id')::uuid),'exhausted abandoned claim becomes failed');
-- Exercise worker leases/check/finish against synthetic jobs only, without contacting mail provider.
update star_private.org_deliveries set status='sending',claim_token=gen_random_uuid(),lease_until=now()+interval '5 minutes' where recipient_id=(select id from inbox_ctx where key='member');
select pg_temp.ok((select public.star_organisation_email_worker((select decrypted_secret from vault.decrypted_secrets where name='organisation_email_worker_secret'),'check',jsonb_build_object('id',d.id,'claim_token',d.claim_token))->>'email'='inbox-test-'||(select id::text from inbox_ctx where key='member')||'@example.invalid' from star_private.org_deliveries d join star_private.org_messages m on m.id=d.message_id where d.recipient_id=(select id from inbox_ctx where key='member') and m.kind='shared_feedback'),'worker resolves live recipient');
-- Withdraw approval: player history, unread counts and queued delivery are unavailable immediately.
update public.star_organisation_players set approved_at=null,approved_by=null where id=(select id from inbox_ctx where key='link');
select pg_temp.ok((select public.star_organisation_email_worker((select decrypted_secret from vault.decrypted_secrets where name='organisation_email_worker_secret'),'check',jsonb_build_object('id',d.id,'claim_token',d.claim_token)) is null from star_private.org_deliveries d join star_private.org_messages m on m.id=d.message_id where d.recipient_id=(select id from inbox_ctx where key='member') and m.kind='shared_feedback'),'withdrawal suppresses queued feedback email');
set local role authenticated;
select set_config('request.jwt.claim.sub',(select id::text from inbox_ctx where key='member'),true);
select pg_temp.denied('thread',jsonb_build_object('organisation_id',(select id from inbox_ctx where key='org'),'thread_id',(select id from inbox_ctx where key='player_thread')));
select pg_temp.denied('send',jsonb_build_object('organisation_id',(select id from inbox_ctx where key='org'),'thread_id',(select id from inbox_ctx where key='player_thread'),'body','Should fail','client_id',gen_random_uuid()));
select pg_temp.ok(jsonb_array_length(public.star_organisation_inbox('list',jsonb_build_object('organisation_id',(select id from inbox_ctx where key='org')))->'threads')=2,'consent withdrawal hides both player conversations, keeps general/request');
reset role;
update public.star_organisation_members set active=false where user_id=(select id from inbox_ctx where key='member');
select pg_temp.ok((select public.star_organisation_email_worker((select decrypted_secret from vault.decrypted_secrets where name='organisation_email_worker_secret'),'check',jsonb_build_object('id',d.id,'claim_token',d.claim_token)) is null from star_private.org_deliveries d join star_private.org_messages m on m.id=d.message_id where d.recipient_id=(select id from inbox_ctx where key='member') and m.kind='message'),'revocation suppresses queued generic reply');
set local role authenticated;
select set_config('request.jwt.claim.sub',(select id::text from inbox_ctx where key='member'),true);
select pg_temp.denied('list',jsonb_build_object('organisation_id',(select id from inbox_ctx where key='org')));
reset role;
update public.star_organisations set active=false where id=(select id from inbox_ctx where key='org');
set local role authenticated;
select set_config('request.jwt.claim.sub',(select id::text from inbox_ctx where key='manager'),true);
select pg_temp.denied('thread',jsonb_build_object('thread_id',(select id from inbox_ctx where key='general')));
reset role;
select 'Organisation inbox access, consent, unread, queue and idempotency checks passed' result;
rollback;
